import * as utilities from "#base/maps/map-utilities.js";
export function generateResources(iWidth: number, iHeight: number, minMarineResourceTypesOverride = 3) {
	const resourceWeight: number[] = new Array(GameInfo.Resources.length);
	const resourceRunningWeight: number[] = new Array(GameInfo.Resources.length);

	const importantResourceRegionalCount: Map<number, number[]> = new Map<number, number[]>();
	const getImportantResourceCounts = (landmassId: number): number[] => {
		if (!importantResourceRegionalCount.has(landmassId)) {
			importantResourceRegionalCount.set(landmassId, new Array(GameInfo.Resources.length).fill(0));
		}
		return importantResourceRegionalCount.get(landmassId)!;
	};

	const resourcesPlacedCount: number[] = new Array(GameInfo.Resources.length);
	let minimumResourcePlacementModifier = utilities.getMinimumResourcePlacementModifier();
	if (minimumResourcePlacementModifier == undefined) {
		minimumResourcePlacementModifier = 0;
	}
	//Initial Resource data
	for (let resourceIdx = 0; resourceIdx < GameInfo.Resources.length; resourceIdx++) {
		resourceWeight[resourceIdx] = 0;
		resourceRunningWeight[resourceIdx] = 0;
		resourcesPlacedCount[resourceIdx] = 0;
	}

	// Find all resources
	class ResourceLandmass {
		typeIdx = 0;
		landmassId = 0;
	}

	const aResourceTypes: ResourceLandmass[] = [];
	const resources: ResourceType[] = ResourceBuilder.getGeneratedMapResources(minMarineResourceTypesOverride);
	for (let ridx = 0; ridx < resources.length; ++ridx) {
		const resourceInfo = GameInfo.Resources.lookup(resources[ridx]);
		if (resourceInfo && resourceInfo.Tradeable) {
			resourceWeight[resourceInfo.$index] = resourceInfo.Weight;
			const landmassId = ResourceBuilder.getResourceLandmass(resourceInfo.$index);
			aResourceTypes.push({ typeIdx: resourceInfo.$index, landmassId: landmassId });
		}
	}

	//Generate Poisson Map
	const seed = GameplayMap.getRandomSeed();
	const avgDistanceBetweenPoints = 3;
	const normalizedRangeSmoothing = 2;
	const poisson = TerrainBuilder.generatePoissonMap(seed, avgDistanceBetweenPoints, normalizedRangeSmoothing);

	const hexDistance2X = [
		{ x: -1, y: -2 }, // NW
		{ x: 1, y: -2 }, // NE
		{ x: -1, y: 2 }, // SW
		{ x: 1, y: 2 }, // SE
	] as const;

	const checkPoissonRegion = (iX: number, iY: number) => {
		const index = iY * iWidth + iX;
		const coord: float2 = { x: iX, y: iY };
		if (poisson[index] >= 1) return true;

		// We want slightly more density than the poisson map provides, so also pass the poisson check if at least 2 out of
		// the 4 points that are a distance of 2 away in an X pattern pass the poisson check.
		let score = 0;
		for (const offset of hexDistance2X) {
			const adjLoc = { x: coord.x + offset.x, y: coord.y + offset.y };
			if (adjLoc.x >= 0 && adjLoc.x < iWidth && adjLoc.y >= 0 && adjLoc.y < iHeight) {
				const adjIndex = adjLoc.y * iWidth + adjLoc.x;
				if (poisson[adjIndex] >= 1) ++score;
			}
		}
		return score >= 2;
	};

	for (let iY: number = iHeight - 1; iY >= 0; iY--) {
		for (let iX = 0; iX < iWidth; iX++) {
			if (checkPoissonRegion(iX, iY)) {
				//Generate a list of valid resources at this plot
				const resources: number[] = [];
				const landmassRegionId = GameplayMap.getLandmassRegionId(iX, iY);

				aResourceTypes.forEach((resourceLandmass) => {
					const assignedLandmass = resourceLandmass.landmassId;
					const allowedOnLandmass =
						assignedLandmass == LandmassRegion.LANDMASS_REGION_ANY ||
						(assignedLandmass != LandmassRegion.LANDMASS_REGION_NONE &&
							landmassRegionId != LandmassRegion.LANDMASS_REGION_DEFAULT &&
							assignedLandmass % landmassRegionId == 0);

					if (allowedOnLandmass && canHaveResource(iX, iY, resourceLandmass.typeIdx)) {
						resources.push(resourceLandmass.typeIdx);
					}
				});

				//Select the heighest weighted (ties are a coin flip) resource
				if (resources.length > 0) {
					let resourceChosen: number = resources[0];
					for (let iI = 1; iI < resources.length; iI++) {
						if (GameplayMap.isNavigableRiver(iX, iY)) {
							if (ResourceBuilder.isResourceIgnoringWeightForRiverPlacement(resources[iI])) {
								resourceChosen = resources[iI];
								break;
							}
						} else {
							if (resourceRunningWeight[resources[iI]] > resourceRunningWeight[resourceChosen]) {
								resourceChosen = resources[iI];
							} else if (resourceRunningWeight[resources[iI]] == resourceRunningWeight[resourceChosen]) {
								const iRoll = TerrainBuilder.getRandomNumber(2, "Resource Scatter");
								if (iRoll >= 1) {
									resourceChosen = resources[iI];
								}
							}
						}
					}

					//Place the selected resource
					const iResourcePlotIndex: number = getFlowerPlot(iX, iY, resourceChosen);
					if (iResourcePlotIndex != -1) {
						const iLocation: PlotCoord = GameplayMap.getLocationFromIndex(iResourcePlotIndex);
						const iResourceX: number = iLocation.x;
						const iResourceY: number = iLocation.y;
						ResourceBuilder.setResourceType(iResourceX, iResourceY, resourceChosen);
						resourceRunningWeight[resourceChosen] -= resourceWeight[resourceChosen];
						resourcesPlacedCount[resourceChosen]++;
						getImportantResourceCounts(landmassRegionId)[resourceChosen]++;
					} else {
						console.log("Resource Index Failure");
					}
				}
			}
		}
	}

	//Some resources are required for gameplay for the age, if not enough were generated, place them on the map now. Some differences from transition placement but might want to look at making a utility function for these placements.
	for (let iY = 0; iY < iHeight; iY++) {
		for (let iX = 0; iX < iWidth; iX++) {
			const landmassRegionId = GameplayMap.getLandmassRegionId(iX, iY);
			const resourceAtLocation = GameplayMap.getResourceType(iX, iY);
			if (resourceAtLocation == ResourceTypes.NO_RESOURCE) {
				const resourcesEligible: number[] = [];
				for (let i = 0; i < resourcesPlacedCount.length; ++i) {
					const resourceToPlace = GameInfo.Resources.lookup(i);
					if (resourceToPlace) {
						const assignedLandmass = ResourceBuilder.getResourceLandmass(i);
						const allowedOnLandmass =
							landmassRegionId != LandmassRegion.LANDMASS_REGION_DEFAULT &&
							(assignedLandmass == LandmassRegion.LANDMASS_REGION_ANY ||
								(assignedLandmass != LandmassRegion.LANDMASS_REGION_NONE &&
									assignedLandmass % landmassRegionId == 0));
						if (allowedOnLandmass) {
							const minimumPerLandMass =
								resourceToPlace.MinimumPerHemisphere > 0
									? resourceToPlace.MinimumPerHemisphere + minimumResourcePlacementModifier
									: 0;
							if (
								getImportantResourceCounts(landmassRegionId)[i] < minimumPerLandMass &&
								ResourceBuilder.isResourceRequiredForAge(i, Game.age) &&
								ResourceBuilder.canHaveResource(iX, iY, i, false) &&
								!wouldCreateCluster(iX, iY)
							) {
								//Try not to place adjacent to other resources. The new Poission map causes the old one to be ignored, which causes clumping.
								resourcesEligible.push(i);
							}
						}
					}
				}

				//Select the heighest weighted (ties are a coin flip) resource
				let resourceChosenIndex = -1;
				if (resourcesEligible.length > 0) {
					let resourceChosen: ResourceType = ResourceTypes.NO_RESOURCE;
					for (let iI = 0; iI < resourcesEligible.length; iI++) {
						if (resourceChosen == ResourceTypes.NO_RESOURCE) {
							resourceChosen = resourcesEligible[iI];
							resourceChosenIndex = resourcesEligible[iI];
						} else {
							if (
								resourceRunningWeight[resourcesEligible[iI]] >
								resourceRunningWeight[resourceChosenIndex]
							) {
								resourceChosen = resourcesEligible[iI];
								resourceChosenIndex = resourcesEligible[iI];
							} else if (
								resourceRunningWeight[resourcesEligible[iI]] ==
								resourceRunningWeight[resourceChosenIndex]
							) {
								const iRoll = TerrainBuilder.getRandomNumber(2, "Resource Scatter");
								if (iRoll >= 1) {
									resourceChosen = resourcesEligible[iI];
									resourceChosenIndex = resourcesEligible[iI];
								}
							}
						}
					}
				}

				if (resourceChosenIndex > -1) {
					ResourceBuilder.setResourceType(iX, iY, resourceChosenIndex);
					resourceRunningWeight[resourceChosenIndex] -= resourceWeight[resourceChosenIndex];
					const name: any = GameInfo.Resources.lookup(resourceChosenIndex)?.Name;
					console.log("Force Placed " + Locale.compose(name) + " at (" + iX + ", " + iY + ")");
					getImportantResourceCounts(landmassRegionId)[resourceChosenIndex]++;
				}
			}
		}
	}

	const definition = GameInfo.Ages.lookup(Game.age);
	if (definition) {
		const mapType = Configuration.getMapValue("Name");
		for (const option of GameInfo.MapIslandBehavior) {
			if (option.MapType === mapType) {
				utilities.replaceIslandResources(iWidth, iHeight, option.ResourceClassType);
			}
		}
	}

	// Optional debug log of required minimum per landmass after all placement passes
	//utilities.auditMinimumResourcesPlacement(iWidth, iHeight);
}

//Would have cluster of same resource on adjacent tiles?
//If resource type is not defined, will count ANY resource adjacent
export function wouldCreateCluster(x: number, y: number, resourceType?: ResourceType, maxAdjacent = 1): boolean {
	let count = 0;
	const pos: float2 = { x: x, y: y };
	for (let dir: DirectionTypes = 0; dir < DirectionTypes.NUM_DIRECTION_TYPES; dir++) {
		const adjLoc = GameplayMap.getAdjacentPlotLocation(pos, dir);
		const adjResource = GameplayMap.getResourceType(adjLoc.x, adjLoc.y);
		const matches =
			resourceType == undefined ? adjResource != ResourceTypes.NO_RESOURCE : adjResource === resourceType;
		if (matches) {
			count++;
			if (count >= maxAdjacent) return true;
		}
	}
	return false;
}

//Can I have a resource in this tile and it wouldn't create a cluster?
export function canHaveResource(iX: number, iY: number, resourceType: ResourceType): boolean {
	if (ResourceBuilder.canHaveResource(iX, iY, resourceType, false) && !wouldCreateCluster(iX, iY, resourceType)) {
		return true;
	}
	return false;
}

//Return a plot index for this resource
//First choosing the initial plot, otherwise it randomly chooses a valid plot from the sorounding ring
export function getFlowerPlot(iX: number, iY: number, resourceType: ResourceType): number {
	if (ResourceBuilder.canHaveResource(iX, iY, resourceType, false) && !wouldCreateCluster(iX, iY, resourceType)) {
		return GameplayMap.getIndexFromXY(iX, iY);
	}

	const resourcePlotIndexes: number[] = [];
	for (let iDirection: DirectionTypes = 0; iDirection < DirectionTypes.NUM_DIRECTION_TYPES; iDirection++) {
		const iIndex: number = GameplayMap.getIndexFromXY(iX, iY);
		const iLocation: PlotCoord = GameplayMap.getLocationFromIndex(iIndex);
		const iAdjacentX: number = GameplayMap.getAdjacentPlotLocation(iLocation, iDirection).x;
		const iAdjacentY: number = GameplayMap.getAdjacentPlotLocation(iLocation, iDirection).y;
		const iAdjacentIndex: number = GameplayMap.getIndexFromXY(iAdjacentX, iAdjacentY);
		if (
			ResourceBuilder.canHaveResource(iAdjacentX, iAdjacentY, resourceType, false) &&
			!wouldCreateCluster(iAdjacentX, iAdjacentY, resourceType)
		) {
			resourcePlotIndexes.push(iAdjacentIndex);
		}
	}

	if (resourcePlotIndexes.length > 0) {
		return utilities.shuffle(resourcePlotIndexes)[0];
	} else {
		return -1;
	}
}
